import itertools
# Fix stems strong-GC, vary pos7,14 (loop neighbors of lone pair) and pos28,29 (junction)
fixed={1:'A',2:'G',3:'C',4:'G',5:'G',6:'G',8:'A',9:'A',10:'A',11:'A',12:'A',13:'A',15:'C',16:'G',17:'C',18:'G',19:'G',20:'A',21:'A',22:'A',23:'A',24:'C',25:'C',26:'G',27:'C',30:'C',31:'C',32:'G',33:'C',34:'A',35:'A',36:'A',37:'A',38:'A',39:'A',40:'A'}
seqs=[]
for p7 in 'GCU':
  for p14 in 'GCU':
    for p28 in 'GCU':
      for p29 in 'GCU':
        p=dict(fixed)
        p[7]=p7; p[14]=p14; p[28]=p28; p[29]=p29
        seqs.append(''.join(p[i] for i in range(1,41)))
import json
print(json.dumps(seqs[:81]))
" > /tmp/seqs2.json
python3 -c "import json;print(len(json.load(open('/tmp/seqs2.json'))))"

